public class Main {
    public static void main(String[] args) {
        try {
            int[] marks = {90, 80}; //~ An array with two slots: valid indexes are 0 and 1.
            System.out.println(marks[5]); //~ Index 5 doesn't exist, so Java THROWS ArrayIndexOutOfBoundsException and jumps straight to catch.
            System.out.println("never runs"); //~ Skipped: the throw already jumped out of the try block.
        } catch (ArrayIndexOutOfBoundsException e) { //~ This catch matches the thrown type, so it handles it.
            System.out.println("Caught: bad index");
        } finally {
            System.out.println("Finally always runs"); //~ finally runs whether or not something was thrown.
        }
        System.out.println("Still alive"); //~ The exception was handled, so the program carries on normally.
    }
}

